def cap(name):
    hook, lines, cta, tags = C[name]
    return hook + "\n\n" + "\n".join(lines) + "\n\n" + cta + "\n\n" + tags + " " + TAGS_CORE
if __name__ == "__main__":
    for k in C: print(cap(k)); print("-----")
